-- SOURCE: 20261102000000_add_workout_substitutions.sql
-- Session-only substitutions. Apply in development/staging before the app update.
alter table public.gym_workout_exercises
  add column if not exists substitution_version integer not null default 0 check (substitution_version >= 0),
  add column if not exists substitution_details jsonb,
  add column if not exists substitution_history jsonb not null default '[]'::jsonb check (jsonb_typeof(substitution_history) = 'array');

create or replace function public.gym_guard_workout_substitution()
returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  -- A template's ON DELETE SET NULL is not a substitution, including in history.
  if new.exercise_id is null and old.exercise_id is not null
    and (to_jsonb(new) - 'exercise_id' - 'updated_at') = (to_jsonb(old) - 'exercise_id' - 'updated_at') then return new; end if;

  if new.name is distinct from old.name or new.exercise_id is distinct from old.exercise_id
    or new.substitution_details is distinct from old.substitution_details then
    if old.completed then raise exception 'Completed exercises cannot be replaced'; end if;
    new.substitution_history := old.substitution_history || jsonb_build_array(jsonb_build_object(
      'name', old.name, 'exercise_id', old.exercise_id, 'weight', old.weight,
      'target_sets', old.target_sets, 'target_reps', old.target_reps,
      'details', old.substitution_details, 'swapped_at', clock_timestamp()));
    new.substitution_version := old.substitution_version + 1;
    new.exercise_id := null;
    new.weight := null;
    new.completed := false;
  else
    if new.substitution_history is distinct from old.substitution_history
      or new.substitution_version is distinct from old.substitution_version then
      raise exception 'Substitution history is managed automatically';
    end if;
    -- Old app tabs have no version token. They may not write progress onto a replacement.
    -- This transaction-local marker is a concurrency check; ownership is enforced by RLS.
    if old.substitution_version > 0 and (new.weight is distinct from old.weight or new.completed is distinct from old.completed)
      and current_setting('gym.snapshot_write', true) is distinct from old.id::text || ':' || old.substitution_version::text then
      raise exception 'Exercise changed; refresh the workout';
    end if;
  end if;
  return new;
end;
$$;
drop trigger if exists gym_workout_exercises_guard_substitution on public.gym_workout_exercises;
create trigger gym_workout_exercises_guard_substitution before update on public.gym_workout_exercises
for each row execute function public.gym_guard_workout_substitution();
revoke all on function public.gym_guard_workout_substitution() from public;

create or replace function public.gym_update_workout_progress(target_workout_id uuid, target_exercise_id uuid, expected_version integer, changes jsonb)
returns uuid language plpgsql security invoker set search_path = '' as $$
declare current_status text; snapshot public.gym_workout_exercises;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if changes is null or jsonb_typeof(changes) <> 'object' or changes = '{}'::jsonb
    or changes - 'weight' - 'completed' <> '{}'::jsonb then raise exception 'Invalid progress'; end if;
  if changes ? 'weight' and (jsonb_typeof(changes->'weight') not in ('number', 'null')
    or (changes->>'weight')::numeric < 0) then raise exception 'Invalid weight'; end if;
  if changes ? 'completed' and jsonb_typeof(changes->'completed') <> 'boolean' then raise exception 'Invalid completion'; end if;
  select status into current_status from public.gym_workouts where id = target_workout_id and user_id = auth.uid() for update;
  if current_status is null then raise exception 'Workout not found'; end if;
  if current_status <> 'in_progress' then raise exception 'Workout is no longer in progress'; end if;
  select * into snapshot from public.gym_workout_exercises where id = target_exercise_id and workout_id = target_workout_id for update;
  if snapshot.id is null then raise exception 'Exercise not found'; end if;
  if expected_version is distinct from snapshot.substitution_version then raise exception 'Exercise changed; refresh the workout'; end if;
  perform set_config('gym.snapshot_write', snapshot.id::text || ':' || expected_version::text, true);
  update public.gym_workout_exercises set
    weight = case when changes ? 'weight' then (changes->>'weight')::numeric else weight end,
    completed = case when changes ? 'completed' then (changes->>'completed')::boolean else completed end
    where id = target_exercise_id;
  perform set_config('gym.snapshot_write', '', true);
  return target_exercise_id;
end;
$$;
revoke all on function public.gym_update_workout_progress(uuid, uuid, integer, jsonb) from public;
grant execute on function public.gym_update_workout_progress(uuid, uuid, integer, jsonb) to authenticated;

create or replace function public.gym_swap_workout_exercise(target_workout_id uuid, target_exercise_id uuid,
  expected_version integer, expected_updated_at timestamptz, source_muscle text, replacement jsonb)
returns uuid language plpgsql security invoker set search_path = '' as $$
declare current_status text; snapshot public.gym_workout_exercises; known_muscle text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if replacement is null or jsonb_typeof(replacement) <> 'object'
    or length(replacement::text) > 20000
    or replacement - 'id' - 'name' - 'primaryMuscle' - 'equipment' - 'instructions' - 'mechanic' <> '{}'::jsonb
    or jsonb_typeof(replacement->'id') is distinct from 'string'
    or jsonb_typeof(replacement->'name') is distinct from 'string'
    or jsonb_typeof(replacement->'equipment') is distinct from 'string'
    or coalesce(length(trim(replacement->>'id')), 0) not between 1 and 160
    or coalesce(length(trim(replacement->>'name')), 0) not between 1 and 160
    or coalesce(length(trim(replacement->>'equipment')), 0) not between 1 and 120
    or source_muscle is null or source_muscle not in ('Chest','Back','Shoulders','Biceps','Triceps','Quadriceps','Hamstrings','Glutes','Calves','Abs/Core')
    or (replacement->>'primaryMuscle') is distinct from source_muscle
    or jsonb_typeof(replacement->'instructions') is distinct from 'array' then raise exception 'Invalid replacement'; end if;
  if replacement ? 'mechanic' and replacement->'mechanic' <> 'null'::jsonb
    and replacement->>'mechanic' not in ('compound', 'isolation') then raise exception 'Invalid replacement'; end if;
  if jsonb_array_length(replacement->'instructions') > 12 or exists (select 1 from jsonb_array_elements(replacement->'instructions') step
    where jsonb_typeof(step) <> 'string' or length(step #>> '{}') > 1000) then raise exception 'Invalid instructions'; end if;

  select status into current_status from public.gym_workouts where id = target_workout_id and user_id = auth.uid() for update;
  if current_status is null then raise exception 'Workout not found'; end if;
  if current_status <> 'in_progress' then raise exception 'Workout is no longer in progress'; end if;
  select * into snapshot from public.gym_workout_exercises where id = target_exercise_id and workout_id = target_workout_id for update;
  if snapshot.id is null then raise exception 'Exercise not found'; end if;
  if snapshot.completed then raise exception 'Completed exercises cannot be replaced'; end if;
  if expected_version is distinct from snapshot.substitution_version or expected_updated_at is distinct from snapshot.updated_at then
    raise exception 'Exercise changed; refresh the workout'; end if;
  known_muscle := snapshot.substitution_details->>'primaryMuscle';
  if known_muscle is null then select muscle_group into known_muscle from public.gym_exercises where id = snapshot.exercise_id; end if;
  if known_muscle is not null and known_muscle <> source_muscle then raise exception 'Replacement must keep the primary muscle'; end if;
  if exists (select 1 from public.gym_workout_exercises e where e.workout_id = target_workout_id and
    (lower(trim(e.name)) = lower(trim(replacement->>'name')) or e.substitution_details->>'id' = replacement->>'id')) then
    raise exception 'Exercise is already in this workout'; end if;
  update public.gym_workout_exercises set name = replacement->>'name', substitution_details = replacement
    where id = target_exercise_id;
  return target_exercise_id;
end;
$$;
revoke all on function public.gym_swap_workout_exercise(uuid, uuid, integer, timestamptz, text, jsonb) from public;
grant execute on function public.gym_swap_workout_exercise(uuid, uuid, integer, timestamptz, text, jsonb) to authenticated;

-- SOURCE: 20261102020000_add_workout_set_logging.sql
-- Actual set records live with the owned, immutable workout snapshot.
alter table public.gym_workout_exercises
  add column if not exists logged_sets jsonb not null default '[]'::jsonb,
  add column if not exists log_revision integer not null default 0 check (log_revision >= 0);

create or replace function public.gym_validate_set_log()
returns trigger language plpgsql security invoker set search_path = '' as $$
declare item jsonb; seen integer[] := '{}'; position integer;
begin
  if jsonb_typeof(new.logged_sets) is distinct from 'array' or jsonb_array_length(new.logged_sets) > 100 then raise exception 'Invalid set log'; end if;
  for item in select value from jsonb_array_elements(new.logged_sets) loop
    if jsonb_typeof(item) is distinct from 'object' or item - 'set' - 'reps' - 'weight' - 'completed' <> '{}'::jsonb
      or not (item ?& array['set','reps','weight','completed'])
      or jsonb_typeof(item->'set') is distinct from 'number'
      or (item->>'set')::numeric <> trunc((item->>'set')::numeric)
      or (item->>'set')::numeric not between 1 and 100
      or jsonb_typeof(item->'completed') is distinct from 'boolean'
      or jsonb_typeof(item->'reps') not in ('number','null')
      or jsonb_typeof(item->'weight') not in ('number','null') then raise exception 'Invalid set log'; end if;
    position := (item->>'set')::integer;
    if position = any(seen) then raise exception 'Duplicate set number'; end if;
    seen := array_append(seen, position);
    if item->'reps' <> 'null'::jsonb and ((item->>'reps')::numeric <> trunc((item->>'reps')::numeric) or (item->>'reps')::numeric not between 0 and 1000) then raise exception 'Invalid reps'; end if;
    if (item->>'completed')::boolean and (item->'reps' = 'null'::jsonb or (item->>'reps')::numeric < 1) then raise exception 'Enter reps for completed sets'; end if;
    if item->'weight' <> 'null'::jsonb and (item->>'weight')::numeric not between 0 and 100000 then raise exception 'Invalid weight'; end if;
  end loop;
  if tg_op = 'INSERT' then
    if new.log_revision <> 0 then raise exception 'Set revision is managed automatically'; end if;
  else
    if old.logged_sets <> '[]'::jsonb and new.logged_sets = old.logged_sets and (new.weight is distinct from old.weight or new.completed is distinct from old.completed) then raise exception 'Use the set logger to update recorded sets'; end if;
    if new.log_revision is distinct from old.log_revision then raise exception 'Set revision is managed automatically'; end if;
    if new.logged_sets is distinct from old.logged_sets then new.log_revision := old.log_revision + 1; end if;
  end if;
  return new;
end;
$$;
drop trigger if exists gym_workout_exercises_zz_guard_sets on public.gym_workout_exercises;
create trigger gym_workout_exercises_zz_guard_sets before insert or update on public.gym_workout_exercises
for each row execute function public.gym_validate_set_log();
revoke all on function public.gym_validate_set_log() from public;

create or replace function public.gym_save_workout_sets(target_workout_id uuid, target_exercise_id uuid, expected_version integer, expected_revision integer, sets jsonb)
returns uuid language plpgsql security invoker set search_path = '' as $$
declare parent_status text; snapshot public.gym_workout_exercises;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  select status into parent_status from public.gym_workouts where id = target_workout_id and user_id = auth.uid() for update;
  if parent_status is null then raise exception 'Workout not found'; end if;
  if parent_status <> 'in_progress' then raise exception 'Workout is no longer in progress'; end if;
  select * into snapshot from public.gym_workout_exercises where id = target_exercise_id and workout_id = target_workout_id for update;
  if snapshot.id is null then raise exception 'Exercise not found'; end if;
  if expected_version is distinct from snapshot.substitution_version or expected_revision is distinct from snapshot.log_revision then raise exception 'Set log changed; refresh before saving'; end if;
  if jsonb_typeof(sets) is distinct from 'array' then raise exception 'Invalid set log'; end if;
  perform set_config('gym.snapshot_write', snapshot.id::text || ':' || expected_version::text, true);
  update public.gym_workout_exercises set logged_sets = sets,
    completed = jsonb_array_length(sets) > 0 and not exists(select 1 from jsonb_array_elements(sets) item where item->'completed' is distinct from 'true'::jsonb),
    weight = (select (item->>'weight')::numeric from jsonb_array_elements(sets) item where item->'completed' = 'true'::jsonb order by (item->>'set')::integer desc limit 1)
    where id = target_exercise_id;
  perform set_config('gym.snapshot_write', '', true);
  return target_exercise_id;
end;
$$;
revoke all on function public.gym_save_workout_sets(uuid, uuid, integer, integer, jsonb) from public;
grant execute on function public.gym_save_workout_sets(uuid, uuid, integer, integer, jsonb) to authenticated;

-- Substitution archives actual sets before clearing the replacement.
create or replace function public.gym_guard_workout_substitution()
returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  -- A template's ON DELETE SET NULL is not a substitution, including in history.
  if new.exercise_id is null and old.exercise_id is not null
    and (to_jsonb(new) - 'exercise_id' - 'updated_at') = (to_jsonb(old) - 'exercise_id' - 'updated_at') then return new; end if;

  if new.name is distinct from old.name or new.exercise_id is distinct from old.exercise_id
    or new.substitution_details is distinct from old.substitution_details then
    if old.completed then raise exception 'Completed exercises cannot be replaced'; end if;
    new.substitution_history := old.substitution_history || jsonb_build_array(jsonb_build_object(
      'name', old.name, 'exercise_id', old.exercise_id, 'weight', old.weight,
      'target_sets', old.target_sets, 'target_reps', old.target_reps,
      'logged_sets', old.logged_sets, 'details', old.substitution_details, 'swapped_at', clock_timestamp()));
    new.substitution_version := old.substitution_version + 1;
    new.exercise_id := null;
    new.weight := null;
    new.logged_sets := '[]'::jsonb;
    new.completed := false;
  else
    if new.substitution_history is distinct from old.substitution_history
      or new.substitution_version is distinct from old.substitution_version then
      raise exception 'Substitution history is managed automatically';
    end if;
    -- Old app tabs have no version token. They may not write progress onto a replacement.
    -- This transaction-local marker is a concurrency check; ownership is enforced by RLS.
    if old.substitution_version > 0 and (new.weight is distinct from old.weight or new.completed is distinct from old.completed)
      and current_setting('gym.snapshot_write', true) is distinct from old.id::text || ':' || old.substitution_version::text then
      raise exception 'Exercise changed; refresh the workout';
    end if;
  end if;
  return new;
end;
$$;

-- SOURCE: 20261102030000_add_session_adaptations.sql
-- Reversible session scope: snapshots and saved plans are never deleted.
alter table public.gym_workout_exercises add column if not exists deferred boolean not null default false;
alter table public.gym_workouts
  add column if not exists session_mode text not null default 'full' check (session_mode in ('full','short','comeback')),
  add column if not exists mode_minutes integer check (mode_minutes is null or mode_minutes in (15,20,30)),
  add column if not exists mode_revision integer not null default 0 check (mode_revision >= 0),
  add column if not exists session_adaptations jsonb not null default '[]'::jsonb check (jsonb_typeof(session_adaptations) = 'array');

create or replace function public.gym_guard_deferred_exercise()
returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  if new.deferred and (new.completed or new.logged_sets <> '[]'::jsonb) then raise exception 'Logged work cannot be deferred'; end if;
  -- Restore before editing; preserve template ON DELETE SET NULL compatibility.
  if old.deferred and new.deferred and
    (to_jsonb(new)-'exercise_id'-'updated_at') is distinct from (to_jsonb(old)-'exercise_id'-'updated_at') then
    raise exception 'Restore this exercise before logging or replacing it';
  end if;
  return new;
end;
$$;
drop trigger if exists gym_workout_exercises_guard_deferred on public.gym_workout_exercises;
create trigger gym_workout_exercises_guard_deferred before update on public.gym_workout_exercises
for each row execute function public.gym_guard_deferred_exercise();
revoke all on function public.gym_guard_deferred_exercise() from public;

create or replace function public.gym_guard_session_adaptation()
returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  if old.status <> 'in_progress' and (new.session_mode is distinct from old.session_mode or new.mode_minutes is distinct from old.mode_minutes or new.mode_revision is distinct from old.mode_revision or new.session_adaptations is distinct from old.session_adaptations) then raise exception 'Finished session scope cannot change'; end if;
  return new;
end;
$$;
drop trigger if exists gym_workouts_guard_adaptation on public.gym_workouts;
create trigger gym_workouts_guard_adaptation before update on public.gym_workouts
for each row execute function public.gym_guard_session_adaptation();
revoke all on function public.gym_guard_session_adaptation() from public;

create or replace function public.gym_adapt_workout(target_workout_id uuid, target_mode text, minutes integer, expected_revision integer, reviewed_exercises jsonb, keep_exercise_ids uuid[])
returns uuid language plpgsql security invoker set search_path = '' as $$
declare session public.gym_workouts; item public.gym_workout_exercises; review jsonb; deferred_ids uuid[];
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if target_mode is null or target_mode not in ('full','short','comeback')
    or (target_mode='short' and (minutes is null or minutes not in (15,20,30)))
    or (target_mode<>'short' and minutes is not null)
    or keep_exercise_ids is null or jsonb_typeof(reviewed_exercises) is distinct from 'array' then raise exception 'Invalid session scope'; end if;
  select * into session from public.gym_workouts where id=target_workout_id and user_id=auth.uid() for update;
  if session.id is null then raise exception 'Workout not found'; end if;
  if session.status <> 'in_progress' then raise exception 'Workout is no longer in progress'; end if;
  if expected_revision is distinct from session.mode_revision then raise exception 'Session changed; review again'; end if;
  if jsonb_array_length(reviewed_exercises) <> (select count(*) from public.gym_workout_exercises where workout_id=target_workout_id)
    or exists(select 1 from unnest(keep_exercise_ids) as requested(id) where not exists(select 1 from public.gym_workout_exercises e where e.id=requested.id and e.workout_id=target_workout_id)) then raise exception 'Invalid session scope'; end if;
  for item in select * from public.gym_workout_exercises where workout_id=target_workout_id order by id for update loop
    select value into review from jsonb_array_elements(reviewed_exercises) where value->>'id'=item.id::text;
    if review is null or (review->>'updatedAt')::timestamptz is distinct from item.updated_at then raise exception 'Exercise changed; review again'; end if;
    if item.completed or item.logged_sets <> '[]'::jsonb then
      if not (item.id=any(keep_exercise_ids)) and target_mode<>'full' then raise exception 'Logged work must stay in the session'; end if;
    end if;
  end loop;
  update public.gym_workout_exercises set deferred=(target_mode<>'full' and not(id=any(keep_exercise_ids))) where workout_id=target_workout_id and deferred is distinct from (target_mode<>'full' and not(id=any(keep_exercise_ids)));
  select array_agg(id order by exercise_order,id) into deferred_ids from public.gym_workout_exercises where workout_id=target_workout_id and deferred;
  update public.gym_workouts set session_mode=target_mode, mode_minutes=minutes, mode_revision=mode_revision+1,
    session_adaptations=session_adaptations || jsonb_build_array(jsonb_build_object('mode',target_mode,'minutes',minutes,'deferred_ids',coalesce(deferred_ids,'{}'::uuid[]),'changed_at',clock_timestamp())) where id=target_workout_id;
  return target_workout_id;
end;
$$;
revoke all on function public.gym_adapt_workout(uuid,text,integer,integer,jsonb,uuid[]) from public;
grant execute on function public.gym_adapt_workout(uuid,text,integer,integer,jsonb,uuid[]) to authenticated;

